wrapping ([`WrapOptions`]). Seeded nodes stay put and the strips are measured around them.

```
use graphlay::{layout, GraphBuilder, GroupId, GroupLanes, LayoutOptions, Node, Size};

let node = |group: u32, lane_key: Option<i64>| Node {
    size: Size::new(80.0, 40.0), group: Some(GroupId(group)), lane_key, ..Node::default()
};
let mut b = GraphBuilder::new();
let order = b.add_node(node(0, None));
let late = b.add_node(node(0, Some(2)));
let early = b.add_node(node(0, Some(1)));
let (item, pack) = (b.add_node(node(1, None)), b.add_node(node(1, None)));
for (s, t) in [(order, late), (order, early), (order, item), (item, pack), (late, pack)] {
    b.connect(s, t);
}
let g = b.build();
let mut o = LayoutOptions::layered_default();
o.order.group_lanes = GroupLanes::Strict;
let l = layout(&g, &o)?;

// One lane per group, stacked down the page without overlapping...
assert_eq!(l.lanes.len(), 2);
assert!(l.lanes[0].rect.max.y <= l.lanes[1].rect.min.y);
// ...every node inside its own group's lane...
for (node, p) in g.nodes.iter().zip(&l.nodes) {
    let lane = l.lanes.iter().find(|lane| lane.group == node.group).expect("a lane");
    assert!(p.center.y - 20.0 >= lane.rect.min.y && p.center.y + 20.0 <= lane.rect.max.y);
}
// ...and, within a lane and a layer, in `lane_key` order.
assert!(l.nodes[early.index()].center.y < l.nodes[late.index()].center.y);
# Ok::<(), graphlay::LayoutError>(())
```

When every node has a seed, read layers and order off the seeds, so filtered views of
one graph keep each node's layer and order. Falls back to `Placement` when an edge would
join two nodes of one layer.

```
use graphlay::{layout, GraphBuilder, Layout, LayoutOptions, SeedMode, Size};

let mut b = GraphBuilder::new();
let [a, m, z] = [(); 3].map(|_| b.add_box(Size::new(80.0, 40.0)));
b.connect(a, m);
b.connect(m, z);
b.connect(a, z);
let full = b.build();
let o = LayoutOptions::layered_default();
let before = layout(&full, &o)?;

// A filtered view without `a -> m`, seeded with the full drawing's positions.
let mut view = full.clone();
view.edges.remove(0);
for (node, placed) in view.nodes.iter_mut().zip(&before.nodes) {
    node.position = Some(placed.center);
}
let ranks = |l: &Layout| l.nodes.iter().map(|p| p.rank).collect::<Vec<_>>();
let kept = layout(&view, &LayoutOptions { seed_mode: SeedMode::Structure, ..o })?;
assert_eq!(ranks(&kept), ranks(&before)); // every node keeps its layer
// Layered afresh, `m` would move into the first layer beside `a`.
assert_eq!(layout(&view, &o)?.nodes[m.index()].rank, Some(0));
# Ok::<(), graphlay::LayoutError>(())
```

LayoutRequest.description:
A layered-layout request: the graph, the preset its options start from, and the fields of
that preset to change.

Every part defaults, so `{}` is a valid request (an empty graph, the layered preset).

```
use graphlay::json::LayoutRequest;
use graphlay::{Direction, RoutingStyle};

let request: LayoutRequest = serde_json::from_str(r#"{
    "graph": {"nodes": [{"size": {"width": 80, "height": 40}},
                        {"size": {"width": 80, "height": 40}}],
              "edges": [{"source": 0, "target": 1}]},
    "preset": "process_map",
    "options": {"routing": {"style": "diagonal"}}
}"#)?;
let (graph, options) = request.split()?;
assert_eq!(options.routing.style, RoutingStyle::Diagonal); // from the patch
assert_eq!(options.direction, Direction::TopBottom); // from the preset
let l = graphlay::layout(&graph, &options)?;
assert!(l.nodes[0].center.y < l.nodes[1].center.y);

// A bad patch is an error that names the field.
let bad: LayoutRequest =
    serde_json::from_str(r#"{"options": {"routing": {"style": "curvy"}}}"#)?;
assert!(bad.split().unwrap_err().starts_with("options.routing.style:"));
# Ok::<(), Box<dyn std::error::Error>>(())
```

parent.description:
The compound this node is drawn inside, if any. Parents must not form a cycle.
[`crate::reroute`] and [`crate::tree::layout`] reject graphs that use it.

A compound's box is its children's drawing plus [`crate::Spacing::compound_padding`] and
[`crate::Spacing::compound_header`], and at least its own [`Node::size`]. Its
[`crate::Placement`] carries that size.

```
use graphlay::{layout, GraphBuilder, LayoutOptions, Node, Rect, Size};

let mut b = GraphBuilder::new();
let order = b.add_box(Size::new(80.0, 40.0));
let billing = b.add_box(Size::new(1.0, 1.0)); // the compound, sized by its children
let inside = Node { size: Size::new(80.0, 40.0), parent: Some(billing), ..Node::default() };
let invoice = b.add_node(inside.clone());
let pay = b.add_node(inside);
b.connect(order, invoice); // crosses billing's border
b.connect(invoice, pay);
let l = layout(&b.build(), &LayoutOptions::layered_default())?;

let boxed = |i: usize| Rect::from_center(l.nodes[i].center, l.nodes[i].size);
let outer = boxed(billing.index());
assert!(outer.width() > 2.0 * 80.0);
for child in [invoice, pay] {
    let inner = boxed(child.index());
    assert!(inner.min.x >= outer.min.x && inner.max.x <= outer.max.x);
    assert!(inner.min.y >= outer.min.y && inner.max.y <= outer.max.y);
}
# Ok::<(), graphlay::LayoutError>(())
```

reverse_for_ranking.description:
Lay this edge out as if it ran `target -> source`, but draw it `source -> target`.

The target gets the lower rank, the route still runs source to target, and the edge is
listed in [`crate::Layout::reversed`]. Use it for edges that point backwards, e.g., a retry.

```
use graphlay::{layout, Edge, GraphBuilder, LayoutOptions, Size};

let mut b = GraphBuilder::new();
let refund = b.add_box(Size::new(100.0, 40.0));
let order = b.add_box(Size::new(100.0, 40.0));
// An arrow from refund to order, drawn as a step back.
let cancels = b.add_edge(Edge { reverse_for_ranking: true, ..Edge::new(refund, order) });
let l = layout(&b.build(), &LayoutOptions::layered_default())?;

assert!(l.nodes[order.index()].center.x < l.nodes[refund.index()].center.x);
assert_eq!(l.reversed, vec![cancels]);
// The polyline still starts on refund's left border.
let start = l.edges[0].points[0];
assert!((start.x - (l.nodes[refund.index()].center.x - 50.0)).abs() < 0.5);
# Ok::<(), graphlay::LayoutError>(())
```

PortHint.description:
Where an edge end must attach to its node, set in [`Edge::source_port`] and
[`Edge::target_port`].

Sides are in output (screen) terms, like [`crate::layout::PortInfo::side`], so [`Side::Top`]
is the drawn top border whatever the [`crate::Direction`]. A hint overrides
[`crate::Routing::port_sides`] and [`Node::port_sides`].

A hinted edge is never bundled ([`crate::Routing::bundle_parallel`]) or merged
([`crate::Routing::merge_edges`]). A self-loop honours only the side, and only when all hinted
loops on its node agree. [`crate::tree::layout`] ignores hints.

```
use graphlay::{layout, Edge, GraphBuilder, LayoutOptions, PortHint, Side, Size};

let mut b = GraphBuilder::new();
let a = b.add_box(Size::new(120.0, 50.0));
let c = b.add_box(Size::new(120.0, 50.0));
// Leave `a` through the middle of its bottom border, and enter `c` from above.
b.add_edge(Edge {
    source_port: Some(PortHint::Offset { side: Side::Bottom, t: 0.0 }),
    target_port: Some(PortHint::Side(Side::Top)),
    ..Edge::new(a, c)
});
let l = layout(&b.build(), &LayoutOptions::layered_default())?;

let route = &l.edges[0];
let (pa, pc) = (l.nodes[0].center, l.nodes[1].center);
assert_eq!(route.source_port.map(|p| p.side), Some(Side::Bottom));
assert_eq!(route.target_port.map(|p| p.side), Some(Side::Top));
let (first, last) = (route.points[0], route.points[route.points.len() - 1]);
assert!((first.x - pa.x).abs() < 0.5 && (first.y - (pa.y + 25.0)).abs() < 0.5);
assert!((last.y - (pc.y - 25.0)).abs() < 0.5);
# Ok::<(), graphlay::LayoutError>(())
```

Direction.description:
Primary flow direction of the layered layout. Default [`Direction::LeftRight`].

The output is in screen coordinates either way (`x` right, `y` down). The direction decides
which axis the layers advance along. Options named in flow terms ([`crate::Margins`],
[`LoopSide`], [`PortSides`]) turn with it. Port hints ([`crate::PortHint`]) and the output
do not.

```
use graphlay::{layout, Direction, GraphBuilder, LayoutOptions, Size};

let mut b = GraphBuilder::new();
let a = b.add_box(Size::new(100.0, 40.0));
let c = b.add_box(Size::new(100.0, 40.0));
b.connect(a, c);
let g = b.build();
let mut o = LayoutOptions::layered_default();

o.direction = Direction::LeftRight; // the default
let across = layout(&g, &o)?;
let gap = across.nodes[1].center.x - across.nodes[0].center.x - 100.0;
assert!((gap - o.spacing.layer_gap).abs() < 0.5);

o.direction = Direction::TopBottom;
let down = layout(&g, &o)?;
// The same layer gap, now between a 40px-tall box and the one below it.
let gap = down.nodes[1].center.y - down.nodes[0].center.y - 40.0;
assert!((gap - o.spacing.layer_gap).abs() < 0.5);
# Ok::<(), graphlay::LayoutError>(())
```

There is no `BottomTop` or `RightLeft`. Mirroring the layer axis would reverse the handedness
the order axis, port sides and routing repairs assume.

merge_edges.description:
Draw a node's forks (edges leaving it) or joins (edges reaching it) on one shared trunk
that branches at a common riser. Default [`MergeEdges::None`]. Orthogonal routing only.
It moves no node, and edges with a port hint are never merged.

```
use graphlay::{layout, GraphBuilder, LayoutOptions, MergeEdges, Size};

let mut b = GraphBuilder::new();
let split = b.add_box(Size::new(80.0, 40.0));
for _ in 0..3 {
    let branch = b.add_box(Size::new(80.0, 40.0));
    b.connect(split, branch);
}
let mut o = LayoutOptions::layered_default();
o.routing.merge_edges = MergeEdges::Forks;
let l = layout(&b.build(), &o)?;

// All three edges leave `split` from one point, and branch where the junctions say.
assert!(l.edges.iter().all(|e| e.points[0] == l.edges[0].points[0]));
assert!(!l.junctions.is_empty());
# Ok::<(), graphlay::LayoutError>(())
```

